from PIL import Image
import numpy as np, colorsys
im=np.array(Image.open('first_frame.png').convert('RGB'))
# print masks for yellow arm and saturated fruits as run extents per row
for y in range(45,132):
 xs=[]
 for x in range(75,170):
  r,g,b=map(int,im[y,x]);
